for name, pairs in changes.items():
    p = root/'fg'/name
    s = p.read_text(encoding='utf-8')
    for old, new in pairs:
        if s.count(old) != 1:
            raise RuntimeError(f'Optional warp patch: expected exactly one match in {name}: {old[:100]}')
        s = s.replace(old,new,1)
    p.write_text(s,encoding='utf-8',newline='\n')
with (root/'fg'/'README.md').open('a',encoding='utf-8') as f:
    f.write('\n## Optional Reflex 2\nReflex 2 Frame Warp is unchecked by default. Stop FG, change the checkbox, then Start. Reflex On + Boost stays enabled. OFF bypasses NGX discovery, allocation, evaluation and depth readback; ON requires the supplied runtime and stops on native errors. No silent fallback.\n')
print('Optional native Frame Warp checkbox and full OFF bypass applied.')
